using UnityEditor;using UnityEditor.Localization;using UnityEngine.Localization.Tables;using System.Linq;
public static class Part14ATranslations { public static object Run(){var c=LocalizationEditorSettings.GetStringTableCollection("Mewgic");foreach(var code in Mewgic.Localization.L.Codes){var t=(StringTable)c.GetTable(code);foreach(var r in Part12CLocalization.Source().Where(x=>x.key.StartsWith("reward.")||x.key=="daily.wait"||x.key=="daily.gift_saved"||x.key=="map.levels_short"||x.key=="map.scroll")){t.AddEntry(r.key,r.values[code]).IsSmart=true;}EditorUtility.SetDirty(t);}EditorUtility.SetDirty(c.SharedData);AssetDatabase.SaveAssets();return new{success=true};} }
